import{_ as n,C as t,o as l,c as r,j as a,a as s,E as c,a2 as p}from"./chunks/framework.Di-jvWLj.js";const C=JSON.parse('{"title":"Kubernetes & Flux","description":"","frontmatter":{},"headers":[],"relativePath":"deployment/kubernetes.md","filePath":"deployment/kubernetes.md","lastUpdated":1793004497000}'),d={name:"deployment/kubernetes.md"},i={id:"kubernetes-flux",tabindex:"-1"};function h(u,e,m,y,b,E){const o=t("Badge");return l(),r("div",null,[a("h1",i,[e[0]||(e[0]=s("Kubernetes & Flux ",-1)),c(o,{type:"warning",text:"Planned"}),e[1]||(e[1]=s()),e[2]||(e[2]=a("a",{class:"header-anchor",href:"#kubernetes-flux","aria-label":'Permalink to "Kubernetes & Flux <Badge type="warning" text="Planned" />"'},"​",-1))]),e[3]||(e[3]=p(`<div class="warning custom-block"><p class="custom-block-title">Planned</p><p>The Helm chart and the template&#39;s Flux manifests do not exist yet.</p></div><h2 id="helm-chart" tabindex="-1">Helm chart <a class="header-anchor" href="#helm-chart" aria-label="Permalink to &quot;Helm chart&quot;">​</a></h2><p>One shared chart, published to an OCI registry and used by every agent app. Planned contents:</p><ul><li><strong>Deployment</strong> with liveness (<code>/healthz</code>), readiness (<code>/readyz</code>) and startup probes, a long <code>terminationGracePeriodSeconds</code> (about 120 s) and a short <code>preStop</code> sleep, so the app fails readiness, drains and exits cleanly.</li><li><strong>Service</strong> and an optional <strong>Ingress</strong> for webhooks, the API and the UI.</li><li><strong><code>envFrom</code></strong> for one or more Secrets.</li><li>Optional <strong>CronJobs</strong> for the one-shot <code>run-job</code> mode.</li><li>When sandboxes are enabled: a <strong>ServiceAccount and Role</strong> for the sandbox pods (the verbs below), and a <strong>NetworkPolicy</strong> that limits sandbox egress to DNS, the npm registry and GitHub.</li><li>An optional <strong>ServiceMonitor</strong> for Prometheus.</li></ul><p>The values stay small: image, environment, Secrets, ingress, replicas, sandbox and cron jobs.</p><h2 id="graceful-shutdown" tabindex="-1">Graceful shutdown <a class="header-anchor" href="#graceful-shutdown" aria-label="Permalink to &quot;Graceful shutdown&quot;">​</a></h2><p>On <code>SIGTERM</code> the app fails readiness first, stops intake, then calls <code>engine.drain()</code> (which stops the channels, the cron schedule among them, first) within its budget. Runs still in progress are marked <code>interrupted</code> and recovered by another replica or the next pod. The drain deadline must be shorter than the grace period. This part already works in core: see <a href="/guide/recovery#drain">Cancel, Drain &amp; Recovery</a>.</p><h2 id="flux" tabindex="-1">Flux <a class="header-anchor" href="#flux" aria-label="Permalink to &quot;Flux&quot;">​</a></h2><p>Each agent repository gets:</p><ul><li>an <code>OCIRepository</code> for the chart and a <code>HelmRelease</code> with its values,</li><li>an <code>ImageRepository</code> and an <code>ImagePolicy</code> that select the newest <code>main-&lt;sha&gt;-&lt;timestamp&gt;</code> tag (or a semver range),</li><li>an image update marker in the <code>HelmRelease</code>, so Flux commits new tags back to the repository.</li></ul><h2 id="sandboxes-in-the-cluster" tabindex="-1">Sandboxes in the cluster <a class="header-anchor" href="#sandboxes-in-the-cluster" aria-label="Permalink to &quot;Sandboxes in the cluster&quot;">​</a></h2><p><a href="/reference/sandbox#chamvi-sandbox-k8s"><code>@chamvi/sandbox-k8s</code></a> ships today; only the chart that wires it up is planned. Untrusted code runs in one bare pod per workspace (<code>chamvi-ws-&lt;id&gt;</code>):</p><ul><li><code>runAsNonRoot</code> as uid 1000, seccomp <code>RuntimeDefault</code>, a read-only root filesystem, no capabilities, no privilege escalation</li><li><code>automountServiceAccountToken: false</code>, <code>enableServiceLinks: false</code>, no chamvi Secrets or environment</li><li>requests equal to limits for <code>cpu</code>, <code>memory</code> and <code>ephemeral-storage</code>; <code>/workspace</code> an emptyDir with a <code>sizeLimit</code>, <code>/tmp</code> a 512 MiB memory emptyDir; pids through the kubelet&#39;s <code>podPidsLimit</code></li><li><code>restartPolicy: Never</code> and no <code>activeDeadlineSeconds</code>: a workspace pod lives as long as its run (through approval pauses and chamvi restarts) and is found again by label, up to the hard cap <code>limits.maxLifetimeMs</code> (7 days)</li><li>labels <code>app.kubernetes.io/managed-by=chamvi</code>, <code>app.kubernetes.io/component=sandbox</code>, <code>chamvi.dev/run=&lt;runId&gt;</code>, <code>chamvi.dev/workspace=&lt;id&gt;</code> plus your <code>podLabels</code>; the expiry as the annotation <code>chamvi.dev/expires-at</code></li></ul><p>Expired, failed and finished sandbox pods, and the pods of settled runs, are garbage-collected by the provider; each pod carries its <code>chamvi.dev/deployment</code> (<code>CHAMVI_DEPLOYMENT</code>), so deployments sharing a namespace leave each other&#39;s pods alone. Run the pods in their own namespace and give chamvi&#39;s service account this Role there:</p><div class="language-yaml"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#E7C58C;">apiVersion</span><span style="color:#E6DFDE;">: </span><span style="color:#E7C58C;">rbac.authorization.k8s.io/v1</span></span>
<span class="line"><span style="color:#E7C58C;">kind</span><span style="color:#E6DFDE;">: </span><span style="color:#E7C58C;">Role</span></span>
<span class="line"><span style="color:#E7C58C;">metadata</span><span style="color:#E6DFDE;">:</span></span>
<span class="line"><span style="color:#E7C58C;">  name</span><span style="color:#E6DFDE;">: </span><span style="color:#E7C58C;">chamvi-sandbox</span></span>
<span class="line"><span style="color:#E7C58C;">  namespace</span><span style="color:#E6DFDE;">: </span><span style="color:#E7C58C;">agents-sandbox</span></span>
<span class="line"><span style="color:#E7C58C;">rules</span><span style="color:#E6DFDE;">:</span></span>
<span class="line"><span style="color:#E6DFDE;">  - </span><span style="color:#E7C58C;">apiGroups</span><span style="color:#E6DFDE;">: [</span><span style="color:#E7C58C;">&quot;&quot;</span><span style="color:#E6DFDE;">]</span></span>
<span class="line"><span style="color:#E7C58C;">    resources</span><span style="color:#E6DFDE;">: [</span><span style="color:#E7C58C;">&quot;pods&quot;</span><span style="color:#E6DFDE;">]</span></span>
<span class="line"><span style="color:#E7C58C;">    verbs</span><span style="color:#E6DFDE;">: [</span><span style="color:#E7C58C;">&quot;create&quot;</span><span style="color:#E6DFDE;">, </span><span style="color:#E7C58C;">&quot;get&quot;</span><span style="color:#E6DFDE;">, </span><span style="color:#E7C58C;">&quot;list&quot;</span><span style="color:#E6DFDE;">, </span><span style="color:#E7C58C;">&quot;delete&quot;</span><span style="color:#E6DFDE;">]</span></span>
<span class="line"><span style="color:#E6DFDE;">  - </span><span style="color:#E7C58C;">apiGroups</span><span style="color:#E6DFDE;">: [</span><span style="color:#E7C58C;">&quot;&quot;</span><span style="color:#E6DFDE;">]</span></span>
<span class="line"><span style="color:#E7C58C;">    resources</span><span style="color:#E6DFDE;">: [</span><span style="color:#E7C58C;">&quot;pods/exec&quot;</span><span style="color:#E6DFDE;">]</span></span>
<span class="line"><span style="color:#E7C58C;">    verbs</span><span style="color:#E6DFDE;">: [</span><span style="color:#E7C58C;">&quot;get&quot;</span><span style="color:#E6DFDE;">, </span><span style="color:#E7C58C;">&quot;create&quot;</span><span style="color:#E6DFDE;">]</span></span></code></pre></div><p><code>pods/exec</code> needs both <code>get</code> (the exec WebSocket opens with a GET) and <code>create</code> (API servers with the WebSocket-upgrade authorization change).</p><div class="danger custom-block"><p class="custom-block-title">Not a network boundary yet</p><p>Without a NetworkPolicy a workspace pod reaches every service in the cluster, the chamvi API and its database included, and cloud metadata. Until the chart ships its policy, add one that selects <code>app.kubernetes.io/component=sandbox</code> and denies all egress except DNS, GitHub and the npm registry, with the chamvi namespace and <code>169.254.169.254</code> denied explicitly.</p></div><p>A short-lived, narrowly scoped GitHub token for a sandbox that must push is planned.</p><h2 id="replicas" tabindex="-1">Replicas <a class="header-anchor" href="#replicas" aria-label="Permalink to &quot;Replicas&quot;">​</a></h2><p>See <a href="/deployment/replicas">Multiple Replicas</a>.</p>`,20))])}const v=n(d,[["render",h]]);export{C as __pageData,v as default};
